//! Modality descriptions for the Evaluate Modality panel.

pub(super) fn get(key: &str) -> &'static str {
    match key {
        "deontic" => "Deontic Logic \u{2014} norms of obligation, permission, prohibition, waiver. Used for project governance rules, licensing compliance, and rights enforcement.",
        "epistemic" => "Epistemic Logic \u{2014} reasoning about knowledge and belief. K(a, p) means agent a knows p. Used for epistemic status tracking and constituency-aware access.",
        "paraconsistent" => "Paraconsistent Logic \u{2014} tolerates contradictions without explosion. Used when the knowledge graph contains conflicting assertions from multiple sources.",
        "ltl" => "Linear Temporal Logic (LTL) \u{2014} G (\u{25CB} always), F (\u{25C7} eventually), X (next), U (until). Used for roadmap invariants: G(data_integrity) & F(publication_submitted).",
        "ctl" => "Computation Tree Logic (CTL) \u{2014} branching-time temporal logic. A/E (all/exists paths) + G/F/X/U. Used for workflow verification with branching futures.",
        "asp" => "Answer Set Programming (ASP) \u{2014} declarative logic programming with stable model semantics. Used for combinatorial problems like scheduling and resource allocation.",
        "defeasible" => "Defeasible Logic \u{2014} reasoning with defaults that can be defeated by exceptions. Used for project policies with override conditions.",
        "linear" => "Linear Logic \u{2014} resource-sensitive logic where resources are consumed. Used for cost-base tracking and obligation accounting.",
        "description" => "Description Logic (DL) \u{2014} decidable fragments of FOL for ontology reasoning. Used for OWL DL classification, subsumption, and consistency checking.",
        "dialectical" => "Dialectical Logic \u{2014} reasoning through thesis-antithesis-synthesis. Used for structured debate and decision logs.",
        "argumentation" => "Argumentation Framework \u{2014} Dung-style attack/defense graphs. Used for review processes and evidence evaluation.",
        "abductive" => "Abductive Reasoning \u{2014} inference to the best explanation. Used for hypothesis generation from observations.",
        "fuzzy" => "Fuzzy Logic \u{2014} degrees of truth in [0,1]. Used for confidence scoring and partial matching.",
        "probabilistic" => "Probabilistic Reasoning \u{2014} Bayesian networks and probability theory. Used for evidence weighting and risk assessment.",
        "graph_theory" => "Graph Theory \u{2014} algorithms over graph structures (shortest path, centrality, clustering). Used for dependency analysis and contributor networks.",
        "interval" => "Interval Logic \u{2014} reasoning over time intervals (Allen's relations). Used for scheduling and temporal constraints.",
        "manifold_10d" => "Manifold 10D Logic \u{2014} reasoning across the 10-dimensional manifold (spatial, temporal, epistemic, social, legal, financial, technical, environmental, strata, modal).",
        "epistemic_boundaries" => "Epistemic Boundaries \u{2014} reasoning about what agents can and cannot know. Used for information compartmentalization and access control.",
        "modal" => "Modal Logic \u{2014} necessity (\u{25FB}) and possibility (\u{25CB}). Used for policy reasoning and capability gating.",
        "jural" => "Jural Relations (Hohfeld) \u{2014} 8 legal positions: Right/Duty, Privilege/No-Right, Power/Liability, Immunity/Disability. Used for role-based legal analysis.",
        "stit" => "STIT Agency \u{2014} 'Sees To It That' logic for agentive action attribution. Used for accountability and causal responsibility.",
        "causal" => "Causal Liability \u{2014} reasoning about causal chains and liability attribution. Used for deliverable attribution and breach accountability.",
        "responsibility" => "Responsibility / Meta-Guard \u{2014} meta-level reasoning about who is responsible for what. Used for breach accountability and fiduciary duty enforcement.",
        "capacity" => "Capacity Evaluator \u{2014} reasoning about agent capacity to fulfill roles. Used for membership eligibility and role assignment.",
        "delegation" => "Delegation Tracker \u{2014} reasoning about delegation chains, validity, and revocation. Used for project-scoped agency.",
        "contract" => "Contract Formation \u{2014} reasoning about offer, acceptance, consideration, and contract validity. Used for licensing as contract.",
        "consensus" => "Consensus / Partition \u{2014} M-of-N decision making and partition tolerance. Used for review decisions and governance votes.",
        "meta_deontic" => "Meta-Deontic Breach \u{2014} reasoning about norm violations and their consequences. Used for breach logging and enforcement.",
        "value_flow" => "Value Flow / Commons \u{2014} reasoning about value contribution, obligation, and commons paydown. Used for cost-base and TSL state tracking.",
        "interaction_gov" => "Interaction Governance \u{2014} reasoning about permitted/forbidden interactions between agents. Used for project policy enforcement.",
        "identity_fabric" => "Identity Fabric \u{2014} reasoning about identity claims, attestations, and verification. Used for member identity management.",
        "capability_gap" => "Capability Gap Analyzer \u{2014} reasoning about required vs available capabilities. Used for role requirement analysis.",
        "legal_compose" => "Legal Compose \u{2014} composition of legal rules from multiple jurisdictions. Used for cross-jurisdictional compliance.",
        "deontic_compose" => "Deontic Compose \u{2014} composition of deontic norms from multiple sources. Used for multi-stakeholder governance.",
        "clinical_risk" => "Clinical Risk Scorer \u{2014} Framingham 10yr CVD, CHA\u{2082}DS\u{2082}-VASc stroke, SCORE2 European CVD, drug interactions (CYP450), contraindications, FHIR observation validation.",
        "dicom_viewer" => "DICOM Viewer \u{2014} diffusion frame proxy rendering, RGBA8 output, window/level adjustment. Used for medical imaging inspection.",
        "comorbidity" => "Comorbidity Analyzer \u{2014} multi-condition interaction analysis and risk adjustment. Used for clinical decision support.",
        "chemistry" => "Chemistry Modeler \u{2014} SMILES validation, molecular weight, LogP, TPSA, drug-likeness (Lipinski/Veber/Ghose/Egan), functional groups, pKa, chiral centers, green metrics.",
        "physics" => "Physics Simulator \u{2014} Metropolis MCMC, RK4 ODE solver, Kohn-Sham DFT, PINN receptor binding, off-grid energy models (lithium, solar, heat transfer).",
        "ode_solver" => "ODE Solver \u{2014} RK4 time-stepper with chaining, SIMD width detection. Used for continuous dynamics integration.",
        "bioinformatics" => "Bioinformatics Lab \u{2014} Smith-Waterman nucleotide/protein alignment, k-mer frequency, FASTA validation, gene expression, Tanimoto similarity, MinHash, UPGMA tree.",
        "gbm_var" => "GBM / VaR Simulator \u{2014} Geometric Brownian Motion path simulation, Monte Carlo Value-at-Risk with deterministic seeded variants.",
        "diffusion" => "Diffusion Controller \u{2014} diffusion pass execution and reconfiguration. Used for heat equation propagation and signal diffusion.",
        "bytecode_vm" => "Bytecode / VM Inspector \u{2014} WebizenVM opcode trace, register state (16 regs), execution stats, MSB dispatch (direct jump vs lexicon lookup).",
        "slg_arena" => "SLG Arena Inspector \u{2014} 42MB ring buffer, 917,504 Quin slots, rule registry, fixpoint rounds, recent slot ring (512).",
        "forge_compute" => "Forge Compute Probe \u{2014} WGSL/PTX/CUDA/HLSL/MSL/SPIR-V code generation, Top-K, GEMM, FFT, certification, roofline estimation, auto-tuning.",
        "compute_profile" => "Compute Profile \u{2014} GPU adapter capabilities, compute units, VRAM, feature detection across WebGPU/CUDA/Metal/DirectX.",
        "privacy" => "Privacy / HE / DP \u{2014} BFV homomorphic encryption (encrypt/decrypt/add/multiply), differential privacy (Laplace/Gaussian), secure aggregation, key rotation.",
        "model_lifecycle" => "Model Lifecycle \u{2014} state machine: Discovered \u{2192} MappedToDisk \u{2192} StreamingVRAM \u{2192} Active \u{2192} Scrubbing. Thermal governor (Cool/Warm/Critical).",
        "inference_monitor" => "Inference Monitor \u{2014} LLM telemetry, token throughput, KV cache utilization, prefill/decode latency, VRAM allocation.",
        "gguf_tokenizer" => "GGUF Tokenizer Inspector \u{2014} vocab, BPE merges, special tokens, chat family detection, stop tokens, pre-type classification.",
        "p64_weight" => "P64 Weight Inspector \u{2014} 64B headers, tensor entries, CRC-32C verification, 16KB page layout, section serialization.",
        "crdt_sync" => "CRDT / Sync Dashboard \u{2014} LWW resolution, delegated access (Ed25519 proof), suspended transaction queue (depth 32), consensus token application.",
        "agency_merkle" => "Agency / Merkle Inspector \u{2014} scoped Merkle root (BLAKE3), Ed25519 signing, human agency verification, fiduciary metadata stamping, PBKDF2 lane key derivation.",
        "key_vault" => "Key Vault Manager \u{2014} HE key management (8 slots), key rotation policy, Ed25519 signing keys, BFV key generation.",
        "policy_evaluator" => "Policy Evaluator \u{2014} access policy evaluation with sensitivity levels and epistemic status. Used for Wellfair access control.",
        "consent_manager" => "Consent Manager \u{2014} grant, revoke, list consents per scope. Used for health record access control and data sharing agreements.",
        "carrier" => "Carrier / Media Binding \u{2014} payload extraction, media tagging (codec, duration, sample rate), binding verification (hash + signature).",
        "control_feedback" => "Control Feedback \u{2014} control state (setpoint, measured, error, integral, derivative), PID computation, stabilization checking.",
        "likeliness" => "Likeliness \u{2014} likeliness algebra with value, confidence, evidence count. Used for hypothesis ranking and evidence weighting.",
        "qubo" => "QUBO Compiler \u{2014} Quadratic Unconstrained Binary Optimization compilation for combinatorial optimization, scheduling, and clustering.",
        "owl_converter" => "OWL Converter \u{2014} OWL\u{2192}SHACL conversion, OWL materialization, SROIQ classification, consistency checking.",
        "allen_rcc8" => "Allen Interval + RCC8 \u{2014} 7 Allen temporal relations (Before/Meets/Overlaps/Starts/During/Finishes/Equals) and 8 RCC8 spatial relations for region topology.",
        "manifold_logic" => "Manifold Logic \u{2014} continuous-to-fact conversion, absolute value integration, wave valuation (amplitude, frequency, phase, damping).",
        "calculus" => "Calculus \u{2014} RK4 step, Simpson's integration, trapezoidal integration, adaptive step, GPU integration, SIMD width detection (AVX2/NEON).",
        _ => "Select a modality to see its description.",
    }
}
